//! Rust library with a Rust type (exposed to C++ by `cpp_api_from_rust`) that
//! is used by public C++ APIs from `cpp_lib_using_rust_type.h`.  Rust bindings
//! for these C++ APIs (generated by `rust_api_from_cpp`) should refer to the
//! original Rust type.

#[derive(Clone, Copy, Default)]
pub struct RustStruct {
    value: i32,
}

impl RustStruct {
    pub fn new(value: i32) -> Self {
        Self { value }
    }

    pub fn value(&self) -> i32 {
        self.value
    }
}
